  "Users": ["Pengguna"],
  "Users could not be loaded right now. Please try again later.": ["Pengguna tidak dapat dimuat saat ini. Silakan coba lagi nanti."],
  "Users provisioned for this tenant will appear here.": ["Pengguna yang disediakan untuk tenant ini akan muncul di sini."],
